import SwiftUI
import SkydayKit

// Layout language (from the Skyday reference sheet): an illustrated pixel-sky header per tab,
// white rounded cards on a pale sky page, soft-pink streak badge, native tab bar.

// MARK: - Sky header

/// Which original pixel scene to show (asset names generated by Tools/make_sky_art.py).
enum SkyScene: String {
    case today = "SkyToday"
    case todaySunset = "SkyTodaySunset"
    case todayNight = "SkyTodayNight"
    case lists = "SkyLists"
    case progress = "SkyProgress"

    /// Today follows the clock: day until 17:00, sunset until 20:00, night after.
    static func today(hour: Int) -> SkyScene {
        switch hour {
        case 5..<17: return .today
        case 17..<20: return .todaySunset
        default: return .todayNight
        }
    }
}

/// Full-bleed illustrated header. The art is drawn with `.interpolation(.none)` so every
/// art pixel stays sharp; it extends under the status bar and fades into the page colour.
/// Content (titles, badges) is laid out on top, inside the safe area.
struct SkyHeader<Content: View>: View {
    let scene: SkyScene
    let height: CGFloat
    let topInset: CGFloat
    @ViewBuilder var content: () -> Content

    var body: some View {
        ZStack(alignment: .topLeading) {
            Image(scene.rawValue)
                .resizable()
                .interpolation(.none)
                .scaledToFill()
                .frame(height: height + topInset)
                .frame(maxWidth: .infinity)
                .clipped()
                .overlay(alignment: .bottom) {
                    // Soft hand-off into the page so cards can overlap the art.
                    LinearGradient(colors: [SkyColor.page.opacity(0), SkyColor.page], startPoint: .top, endPoint: .bottom)
                        .frame(height: 36)
                }
                .accessibilityHidden(true)

            content()
                .padding(.top, topInset + Space.sm)
                .padding(.horizontal, Space.gutter)
                .frame(maxWidth: .infinity, alignment: .topLeading)
        }
        .frame(height: height + topInset)
    }
}

/// White title text over the sky art, with a soft shadow for legibility on bright clouds.
struct SkyTitle: View {
    let text: String
    var font: Font = SkyFont.skyTitle
    var body: some View {
        Text(text)
            .font(font)
            .foregroundStyle(SkyColor.onSky)
            .shadow(color: SkyColor.skyTextShadow, radius: 3, x: 0, y: 1)
            .fixedSize(horizontal: false, vertical: true)
            .accessibilityAddTraits(.isHeader)
    }
}

/// White circular button used on the sky header (44pt).
struct SkyCircleButton: View {
    let systemImage: String
    let label: String
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            Image(systemName: systemImage)
                .font(.system(size: 17, weight: .bold))
                .foregroundStyle(SkyColor.deepSky)
                .frame(width: 44, height: 44)
                .background(Color.white.opacity(0.95), in: Circle())
                .shadow(color: SkyColor.skyTextShadow.opacity(0.4), radius: 4, x: 0, y: 2)
        }
        .buttonStyle(PressableButtonStyle(scale: 0.92))
        .accessibilityLabel(label)
    }
}

// MARK: - Streak badge

/// Soft-pink capsule: flame + "12 Day Streak". Tapping opens Progress.
struct StreakBadge: View {
    let summary: StreakEngine.Summary
    let action: () -> Void

    private var title: String {
        summary.current == 0 ? "Start a streak" : "\(summary.current) Day Streak"
    }

    var body: some View {
        Button(action: action) {
            HStack(spacing: 6) {
                Image(systemName: "flame.fill")
                    .foregroundStyle(SkyColor.flame)
                    .font(.system(size: 15, weight: .bold))
                Text(title)
                    .font(.system(.subheadline, design: .rounded, weight: .bold))
                    .foregroundStyle(SkyColor.ink)
                if summary.todayQualified {
                    Image(systemName: "checkmark.circle.fill")
                        .font(.system(size: 13, weight: .bold))
                        .foregroundStyle(SkyColor.pinkText)
                        .accessibilityHidden(true)
                }
            }
            .padding(.horizontal, Space.md)
            .frame(minHeight: 44)
            .background(SkyColor.softPink, in: Capsule())
            .overlay(Capsule().strokeBorder(Color.white.opacity(0.9), lineWidth: 1.5))
            .shadow(color: SkyColor.pink.opacity(0.18), radius: 8, x: 0, y: 4)
        }
        .buttonStyle(PressableButtonStyle())
        .accessibilityLabel(summary.todayQualified ? "\(title), today's goal reached" : "\(title), \(summary.remainingToday) more to keep it going")
        .accessibilityHint("Opens Progress")
    }
}

// MARK: - Progress summary card

struct ProgressRing: View {
    let fraction: Double
    var size: CGFloat = 56
    var lineWidth: CGFloat = 6
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        ZStack {
            Circle().stroke(SkyColor.lightSky, lineWidth: lineWidth)
            Circle()
                .trim(from: 0, to: max(0.001, min(1, fraction)))
                .stroke(SkyColor.sky, style: StrokeStyle(lineWidth: lineWidth, lineCap: .round))
                .rotationEffect(.degrees(-90))
            Text("\(Int((fraction * 100).rounded()))%")
                .font(.system(.footnote, design: .rounded, weight: .bold))
                .foregroundStyle(SkyColor.ink)
                .contentTransition(.numericText())
                .minimumScaleFactor(0.7)
        }
        .frame(width: size, height: size)
        .animation(reduceMotion ? nil : Motion.progress, value: fraction)
    }
}

/// "67% · 4 of 6 Tasks completed today ›"
struct ProgressSummaryCard: View {
    let done: Int
    let planned: Int
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            HStack(spacing: Space.md) {
                ProgressRing(fraction: planned == 0 ? 0 : Double(done) / Double(planned))
                VStack(alignment: .leading, spacing: 2) {
                    Text(planned == 0 ? "No tasks planned" : "\(done) of \(planned) Tasks")
                        .font(.system(.headline, design: .rounded, weight: .bold))
                        .foregroundStyle(SkyColor.ink)
                    Text(planned == 0 ? "Add something for today" : (done == planned ? "All done today" : "completed today"))
                        .font(SkyFont.meta)
                        .foregroundStyle(SkyColor.inkSecondary)
                }
                Spacer(minLength: 0)
                Image(systemName: "chevron.right")
                    .font(.system(size: 13, weight: .bold))
                    .foregroundStyle(SkyColor.deepSky)
                    .frame(width: 30, height: 30)
                    .background(SkyColor.lightSky, in: Circle())
            }
            .padding(Space.md)
            .card()
        }
        .buttonStyle(PressableButtonStyle(scale: 0.98))
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("Today's progress")
        .accessibilityValue(planned == 0 ? "No tasks planned" : "\(done) of \(planned) tasks completed")
        .accessibilityHint("Opens your plan for today")
        .accessibilityAddTraits(.isButton)
    }
}

// MARK: - Section header with a square add button

struct SectionAddHeader: View {
    let title: String
    let addLabel: String
    var identifier = "addTaskButton"
    let onAdd: () -> Void

    var body: some View {
        HStack {
            Text(title)
                .font(SkyFont.section)
                .foregroundStyle(SkyColor.ink)
                .accessibilityAddTraits(.isHeader)
            Spacer()
            Button(action: onAdd) {
                Image(systemName: "plus")
                    .font(.system(size: 17, weight: .bold))
                    .foregroundStyle(Color.white)
                    .frame(width: 36, height: 36)
                    .background(SkyColor.sky, in: RoundedRectangle(cornerRadius: Radius.small, style: .continuous))
                    .frame(width: 44, height: 44)
                    .contentShape(Rectangle())
            }
            .buttonStyle(PressableButtonStyle(scale: 0.9))
            .accessibilityLabel(addLabel)
            .accessibilityIdentifier(identifier)
        }
    }
}

// MARK: - Stat card (Progress)

struct StatCard<Icon: View>: View {
    let value: String
    let caption: String
    @ViewBuilder var icon: () -> Icon

    var body: some View {
        VStack(spacing: 6) {
            icon().frame(height: 30)
            Text(value)
                .font(.system(.title2, design: .rounded, weight: .bold))
                .foregroundStyle(SkyColor.ink)
                .contentTransition(.numericText())
                .minimumScaleFactor(0.7)
                .lineLimit(1)
            Text(caption)
                .font(SkyFont.caption)
                .foregroundStyle(SkyColor.inkSecondary)
                .lineLimit(2)
                .multilineTextAlignment(.center)
        }
        .frame(maxWidth: .infinity, minHeight: 110)
        .padding(.vertical, Space.sm)
        .card(radius: Radius.row)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("\(caption), \(value)")
    }
}

// MARK: - List card (Lists)

/// White-to-tint card with the list's icon in its colour, name, count and chevron.
struct ListCard: View {
    let list: TaskList
    let openCount: Int

    var body: some View {
        HStack(spacing: Space.md) {
            Image(systemName: list.icon)
                .font(.system(size: 24, weight: .semibold))
                .foregroundStyle(SkyColor.list(list.color))
                .frame(width: 40, height: 40)
                .accessibilityHidden(true)
            VStack(alignment: .leading, spacing: 2) {
                Text(list.name)
                    .font(.system(.headline, design: .rounded, weight: .bold))
                    .foregroundStyle(SkyColor.ink)
                    .lineLimit(1)
                Text(openCount == 1 ? "1 task" : "\(openCount) tasks")
                    .font(SkyFont.meta)
                    .foregroundStyle(SkyColor.inkSecondary)
            }
            Spacer()
            Image(systemName: "chevron.right")
                .font(.system(size: 15, weight: .bold))
                .foregroundStyle(SkyColor.inkSecondary)
                .accessibilityHidden(true)
        }
        .padding(.horizontal, Space.md)
        .frame(minHeight: 64)
        .background(
            LinearGradient(colors: [Color.white, SkyColor.tint(list.color)], startPoint: .leading, endPoint: .trailing),
            in: RoundedRectangle(cornerRadius: Radius.row, style: .continuous)
        )
        .overlay(RoundedRectangle(cornerRadius: Radius.row, style: .continuous).strokeBorder(Color.white, lineWidth: 1))
        .shadow(color: Color(hex: 0x0593C6, alpha: 0.08), radius: 8, x: 0, y: 4)
        .accessibilityElement(children: .combine)
        .accessibilityLabel("\(list.name), \(openCount) open tasks")
    }
}
